export function roadReplacementPanel(engine,world,index,{initialType,initialTarget,onPreview,onApply,onError}){
 const section=document.createElement('section');section.className='intersection-control road-replacement-control';
 const title=document.createElement('h3');title.textContent='Replace road';section.append(title);
 const targets=engine.roadZoningTargets(world,index);if(!targets.length){const p=document.createElement('p');p.textContent='Select a straight section beside this intersection.';section.append(p);return section;}
 const field=(id,text)=>{const label=document.createElement('label');label.htmlFor=id;label.textContent=text;const select=document.createElement('select');select.id=id;section.append(label,select);return select;};
 const road=field('replacementTarget','Existing section');for(const [i,t]of targets.entries()){const option=document.createElement('option');option.value=t.id;option.textContent=t.label+(targets.length>1?' '+(i+1):'');road.append(option);}road.value=targets.some(t=>t.id===initialTarget)?initialTarget:targets[0].id;
 const type=field('replacementType','Replace with');for(const [id,spec]of Object.entries(engine.ROADS)){const option=document.createElement('option');option.value=id;option.textContent=spec.name+' · '+spec.lanes+' lanes';type.append(option);}type.value=initialType||targets.find(t=>t.id===road.value).type;
 const summary=document.createElement('p');summary.className='replacement-summary';summary.setAttribute('role','status');
 const label=document.createElement('label');label.className='replacement-demolition';const demolition=document.createElement('input');demolition.id='replacementDemolish';demolition.type='checkbox';const text=document.createElement('span');label.append(demolition,text);
 const note=document.createElement('p');note.className='small muted';note.textContent='The arrow shows the one-way direction. Buildings outside the new road footprint keep their lots. This changes the selected section; it does not redraw the curve.';
 const apply=document.createElement('button');apply.id='applyRoadReplacement';apply.type='button';apply.textContent='Replace road';let shown;
 const fingerprint=q=>JSON.stringify([q.target?.id,q.type,q.cost,q.residentsAffected,q.conflicts.map(c=>c.id)]);
 const refresh=()=>{shown=engine.roadReplacementQuote(world,road.value,type.value,{demolish:demolition.checked});label.hidden=!shown.conflicts.length;text.textContent='Remove '+shown.conflicts.length+' highlighted building lot'+(shown.conflicts.length===1?'':'s')+(shown.residentsAffected?' · '+shown.residentsAffected+' residents affected':'');summary.textContent=(shown.target&&shown.target.type!==shown.type?'₡'+shown.cost.toLocaleString()+' · '+engine.ROADS[shown.target.type].name+' → '+engine.ROADS[shown.type].name+'. ':'')+(shown.reason||'Ready to replace.');apply.disabled=!shown.ok;apply.classList.toggle('replacement-destructive',!!shown.conflicts.length&&demolition.checked);onPreview(shown);};
 type.onchange=()=>{demolition.checked=false;refresh();};road.onchange=()=>{demolition.checked=false;refresh();};demolition.onchange=refresh;
 apply.onclick=()=>{const current=engine.roadReplacementQuote(world,road.value,type.value,{demolish:demolition.checked});if(fingerprint(current)!==fingerprint(shown)){refresh();summary.textContent+=' The city changed. Review this updated preview before replacing.';return;}const result=engine.replaceRoad(world,road.value,type.value,{demolish:demolition.checked});if(!result.ok){refresh();onError(result.reason);return;}onApply(result);};
 section.append(summary,label,note,apply);refresh();return section;
}
